/* From Uiverse.io by vinodjangid07  - Website: https://dribbble.com/shots/18149466-Upgrade-to-Pro-Button/attachments/13347110?mode=media - Name: Mobin Madadi - Tags: link, button, hover, active, hover effect, pro, upgrade, redirect */
.__UIV_SCOPE__ .Btn-container {
  width: fit-content;
  height: fit-content;
  border: none;
  background-color: #ebebeb;
  padding: 10px;
  border-radius: 10px;
  box-shadow: 0px 2px 5px #e1e1e1;
  transition: 0.2s;
}
.__UIV_SCOPE__ .inner-wrapper {
  width: fit-content;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f7f7f7;
  border-radius: 5px;
  padding: 8px 15px;
  box-shadow: 0px 4px 10px #d3d3d3;
  gap: 50px;
  transition: 0.2s;
}
.__UIV_SCOPE__ .text {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.__UIV_SCOPE__ .text p {
  font-size: 1.2em;
  font-weight: 600;
  color: rgb(140, 140, 140);
}
.__UIV_SCOPE__ .text .pro {
  background-color: black;
  color: white;
  padding: 4px 8px;
  border-radius: 5px;
}
.__UIV_SCOPE__ .icon {
  width: 40px;
  height: 40px;
  background-color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transform: rotate(45deg);
  transition: 0.2s;
}
.__UIV_SCOPE__ .icon svg {
  width: 15px;
}
.__UIV_SCOPE__ .Btn-container:active {
  transform: scale(1);
}
.__UIV_SCOPE__ .Btn-container:active .inner-wrapper {
  transform: scale(0.97);
}
.__UIV_SCOPE__ .Btn-container:hover .icon {
  transform: rotate(0deg);
}
